'use strict';
if(typeof importScripts==='function')importScripts('./platform/web/push-worker.js');
// API 4 shell cache: replace UI assets without deleting authoritative
// IndexedDB journals or client history. Older published releases remain immutable.
const CACHE='playroom-pwa-v0.21.0-preview.98';
const UPDATE_INFO={"version":"0.21.0-preview.98","releases":[{"version":"0.21.0-preview.98","changes":["Командные метки видны на всех слотах лобби; общие цвета команд закреплены в системе.","Стихии: режимы на 2, 3 и 4 команды, обратное распределение запасов и единый порядок счётчиков жизней.","В результатах параметры ботов расположены под именем, игроки упорядочены по игровым показателям."]},{"version":"0.21.0-preview.97","changes":["Стихии: стандартные командные жетоны на аватарах и синхронное мигание края поля со счётчиком.","В карточках игроков зарезервировано место под выступ жетона, чтобы он не перекрывал имя."]},{"version":"0.21.0-preview.96","changes":["Панель реакций сохраняет положение при появлении и больше не перескакивает вниз.","Стихии: понятные иллюстрации сжатия и короткие подписи; при нуле дополнительных жизней крестик вместо жетона.","Счётчик сжатия Стихий выглядит как поле 4×4: мигают только внешние клетки.","В настройках кнопка темы расположена слева от полноэкранного режима."]},{"version":"0.21.0-preview.95","changes":["Счётчики Стихий выровнены справа: жизни команд перед индикатором сжатия.","Потраченные командные жетоны сохраняют контуры; счёт по центру и компактный вариант при нехватке места.","Центральный квадрат индикатора сжатия получил обводку."]},{"version":"0.21.0-preview.94","changes":["Стихии: командный режим Синие против Красных, общий запас дополнительных жизней и урон союзникам.","Стихии: 0–2 дополнительные жизни; сжатие по потерянным жизням по умолчанию и индикатор на 2, 4 или 6 делений.","Стихии: награда после последнего убийства выдаётся автоматически, без выбора карты.","UNO: места проигравших определяются по очкам оставшихся карт.","Кнопка темы перенесена в шапку настроек; старый блок быстрых клавиш убран."]},{"version":"0.21.0-preview.93","changes":["Названия цветов мест «Коралловый» и «Золотой» заменены на «Красный» и «Желтый»."]},{"version":"0.21.0-preview.92","changes":["Отступы зоны игры совпадают с настройками комнаты; кнопка правил отделена от нижней линии.","Место для управления первым игроком сохраняется во всех играх, поэтому слоты больше не сдвигаются.","Ошибка создания Online-комнаты больше не считается успешным закрытием.","Управление первым игроком стало двухстрочным; положение жетона постоянно во всех режимах, прежний рисунок сохранён."]},{"version":"0.21.0-preview.91","changes":["Закрывающееся лобби сохраняет блокировку повторных нажатий до конца анимации."]},{"version":"0.21.0-preview.90","changes":["При выходе из незапущенного лобби локальная комната и пустая сетевая комната без выданных приглашений закрываются автоматически. Идущие партии сохраняются.","Готовность обозначена зелёным фоном слота и галочкой. Боты отмечены готовыми сразу, лишние подписи готовности убраны."]},{"version":"0.21.0-preview.89","changes":["Шапка игры повторяет компактную компоновку: название над параметрами и кнопкой правил, без лишнего верхнего отступа.","В сводке видны только целые параметры, которые помещаются; слоты игроков стали компактнее при прежних размерах аватаров и текста."]},{"version":"0.21.0-preview.88","changes":["Шапка комнаты стала компактнее: название, важные параметры и переход к настройкам собраны рядом с обложкой.","Любое свободное место шапки открывает параметры игры; обложка и правила сохраняют отдельные действия."]},{"version":"0.21.0-preview.87","changes":["К идущей Online-партии можно подключиться зрителем; его выход сохраняет игру остальных участников.","Подробные карточки комнаты используют актуальную публичную сводку и сохраняют счётчик действий при восстановлении состава."]},{"version":"0.21.0-preview.86","changes":["Комната с другого устройства отображается обычной подробной карточкой в «Моих партиях» и на главной.","Подготовлена поддержка отдельных участников одного аккаунта в одной Online-комнате; для включения требуется обновление серверной схемы."]},{"version":"0.21.0-preview.85","changes":["Исправлены возврат в комнату и переподключение, статусы участников и обновление отметок прочтения чата.","Касание карт пасьянса сохраняет выбор; закрытые карты Пексесо остаются видимыми. Сцены, панели и история сохраняют правильные размеры и актуальные данные.","Компактные карты читаются без перекрытия индексов; пустые основания пасьянса обновляют оформление вместе с картами."]},{"version":"0.21.0-preview.84","changes":["Подготовка к живой приёмке: сохранены принятые масштаб, центровка и компактность параметров; очищены избыточные объявления компоновки."]},{"version":"0.21.0-preview.83","changes":["Широкие схемы команд и флота компактнее по высоте; стулья у общего стола расположены симметрично. Значок последнего раунда уменьшен и упрощён."]},{"version":"0.21.0-preview.82","changes":["Иллюстрации параметров сохраняют размер компонентов между вариантами; постоянная область арта центрирует изображение по обеим осям без растягивания."]},{"version":"0.21.0-preview.81","changes":["Кнопки вариантов параметров подбирают ширину по подписи: короткие варианты остаются в одной строке даже в узких карточках."]},{"version":"0.21.0-preview.80","changes":["Карточки параметров компактнее: убраны лишние отступы над иллюстрациями, мелкие карты, кубики и значки увеличены с сохранением пропорций.","Переброс шестёрок в Лудо показан гранью с шестью точками вместо цифры."]},{"version":"0.21.0-preview.79","changes":["Окно объявления UNO больше не останавливает обычные ходы ботов; защита от ранних обвинений сохранена. Боты Ятци оценивают Шанс с учётом дальнейших возможностей.","Срубание в Лудо показывает подход, возврат срубленных на базы и установку фишки. В ЗиЛ+ фишки на занятой клетке меняются местами после полного перемещения, включая змеи и лестницы.","Редактирование никнейма, имени аккаунта и паролей открывается панелями; уведомления включаются нажатием на свой пункт. Облачные и локальные сохранения используют единую хронологию и подписи. В панели смены игры показана иконка паков.","В настройках есть переключатель светлой и тёмной темы во время игры. При уходе со Звука в Рядом останавливается прослушивание и очищается его статус; пример номера комнаты — 1234. Поиск друзей находит части имени от трёх символов и ставит точное совпадение первым.","Онлайн-игра и Рядом продолжаются при переходе в меню; возврат показывает актуальную партию без старых эффектов и зависших кнопок. Убраны повторные фоновые запросы при возврате в приложение."]},{"version":"0.21.0-preview.78","changes":["Первый ход, места за столом и завершение используют стандартные подписи приложения; в артах первого хода — контурная 1 в кружке.","Стол и стулья в рассадке и Акулине — один компонент. Уточнены схемы шестёрок Лудо и унифицированы рамки режимов Дурака; убраны верхние подписи джокеров."]},{"version":"0.21.0-preview.77","changes":["Выбор опции больше не блокирует закрытие панели свайпом. Свайп работает и по строкам списка игр; короткий тап сохраняет своё действие.","Жест внутри списка закрывает панель у верхней границы; по шапке и нижней области — независимо от прокрутки."]},{"version":"0.21.0-preview.76","changes":["Параметры используют простые стандартные значки приложения с более толстыми линиями. Во всех композициях один общий силуэт игрока без дополнительных линий торса.","Одинаковые настройки пасьянсов используют одинаковые значки.","После потери фокуса или сворачивания панели очищают прерванные касания, чтобы новый свайп снова закрывал панель."]},{"version":"0.21.0-preview.75","changes":["Все служебные иллюстрации параметров приведены к единому тонкому линейному стилю.","Уточнены действия в режимах и сила джокеров Дурака; завершение использует общий endMode без второго имени.","Исправлена разметка Пексесо, упрощён выбор чужой руки Акулины, увеличено поле ЗиЛ."]},{"version":"0.21.0-preview.74","changes":["Общие параметры получили единые иллюстрации первого хода, рассадки и завершения партии.","Заполнены иллюстрации и пояснения параметров Паука, Пексесо, Ятци, Домино, Шашек и ЗиЛ; уточнены схемы Дурака, Акулины и Лудо.","В Косынке уточнено условие штрафа за отмену: только при включённом счёте."]},{"version":"0.21.0-preview.73","changes":["Общие игровые ассеты сохраняют пропорции рамок, скруглений и толщины в игре, миниатюрах, правилах, параметрах и анимациях. Убраны вторые фиксированные рамки и тени поверх SVG.","Пустые карточные слоты, рубашки домино и рамка шашечной доски рисуют материал в собственных координатах. Кубики и показ действий больше не добавляют фиксированную глубину поверх ассета."]},{"version":"0.21.0-preview.72","changes":["Обновление больше не блокируется закрытым лобби не начатой локальной игры. Начатые партии, сетевые комнаты и сохранения остаются защищены."]},{"version":"0.21.0-preview.71","changes":["Правила, параметры и выбор игры заранее готовят публичное содержимое в свободное время. Права, значения и действия проверяются при открытии.","Повторное открытие параметров использует ограниченный кэш размеров; сгруппированы обновления разметки перед измерением. Смена оформления, шрифта, версии игры и ширины не использует старые размеры."]},{"version":"0.21.0-preview.70","changes":["Пояснения параметров закреплены над кнопками; «+» и «−» имеют такую же компактную высоту. Справка расположена ближе к углу карточки.","Ходы Потасовки показаны настоящими картами стихий, типы действий — игровыми значками. Скругления карт и кубиков сохраняют пропорции при уменьшении.","Общий выезд панелей больше не обрывается подготовкой содержимого; при переходах не появляется лишняя горизонтальная полоса. Убраны повторные измерения одинаковых подписей."]},{"version":"0.21.0-preview.69","changes":["Заголовки и справка параметров снова находятся внутри фона карточек. Карточки сохраняют размеры при смене вариантов.","Кнопки вариантов компактнее по высоте; область нажатия остаётся удобной для пальца."]},{"version":"0.21.0-preview.68","changes":["Во время обновления списков сохраняется исходный значок, меняется только фон кнопки. Блок игры в лобби компактнее: название отдельной строкой, краткие параметры слева, правила справа.","Карточки параметров сохраняют место и размер при выборе вариантов. Недоступные параметры затемняются, кнопки выровнены снизу, справка находится справа сверху; убрано повторное значение под иллюстрацией.","Схемы правил снова компактно располагаются сеткой; ограничены широкие фоны, улучшены переносы в таблицах. Дурак получил крупный выбор режима, Косынка — пояснение недоступного лимита проходов Vegas.","Нижние и боковые панели можно потянуть к краю экрана и отпустить для закрытия. Короткое движение возвращает панель на место; обычная прокрутка, ввод и изменение размера сохраняются."]},{"version":"0.21.0-preview.67","changes":["После отправки своего сообщения чат показывает его в видимой области. Входящие сообщения сохраняют место чтения старой переписки; черновик и фокус ввода остаются на месте.","Чаты комнаты и личные переписки сохраняют позицию при повторном открытии. Интерфейс параметров, правил, обучения и истории дополнительно проверен на планшетах, ПК и мобильных экранах в обеих ориентациях."]},{"version":"0.21.0-preview.66","changes":["Параметры игр собраны в компактные карточки: выбранный вариант меняет одну иллюстрацию и подпись, кнопки выбора расположены рядом. Четыре варианта показываются сеткой 2×2.","Крупный блок остаётся только для существенно разных режимов. Иллюстрации количества карт, здоровья, жизней, команд и флотов используют декларативные метаданные паков и общие игровые компоненты.","Нажатие на карточку параметра переключает вариант по кругу, а кнопки выбирают конкретный вариант. Справка и прокрутка выбор не меняют.","Параметры снова разделены на «Порядок игры», «Параметры» и «Завершение». Настройка открытой руки удалена; новые партии используют скрытые руки, старые сохранения сохраняют исходный режим."]},{"version":"0.21.0-preview.65","changes":["Подсказки появляются на первом доступном ходе, сохраняют актуальность при обновлении интерфейса и аккуратно размещаются после поворота экрана. Воспроизведение истории сетевой партии сопровождается звуками показанных действий.","Лобби открывает смену игры по обложке, а параметры — по названию. Режимы представлены карточками, числа — вариантами и счётчиками. Параметры и правила открываются панелями; краткие и полные правила оформлены единообразно.","Главные разделы перелистываются свайпами с сохранением позиции каждого экрана. Исправлены поле и кнопки пасьянсов на телефоне; ручка перестановки игр перенесена влево от обложки."]},{"version":"0.21.0-preview.64","changes":["Загрузка игр и проверка обновлений завершаются понятной ошибкой при отсутствии ответа; после восстановления соединения можно повторить.","После просмотра прошлых ходов в истории снова доступны подтверждение и отмена плана. Иллюстрации правил всех игр сохраняют исходный масштаб и пропорции."]},{"version":"0.21.0-preview.63","changes":["Мини-руки соперников сохраняют полную ширину карт; подписи учитывают увеличенный системный шрифт.","Подготовлен кандидат для проверки интерфейса, обновления и сетевых партий перед стабильным выпуском."]},{"version":"0.21.0-preview.62","changes":["Синяя подсветка следующего игрока стала общей функцией движка для пошаговых игр. Учитываются направление очереди, выбывшие участники и особенности правил пака.","Подсветка восстанавливается локально, в сети и на Столе; одновременное планирование и завершённые партии не показывают ложного следующего игрока. Обновите приложение и паки через «Обновить всё»."]},{"version":"0.21.0-preview.61","changes":["Одна кнопка «Обновить всё» обновляет приложение и установленные игры. После перезапуска обновление паков продолжается автоматически.","Все новые паки загружаются и проверяются до установки. Старые неиспользуемые версии очищаются после успешного обновления; версии для сохранённых партий остаются. При ошибке можно продолжить обновление."]},{"version":"0.21.0-preview.60","changes":["Допустимые действия, предпросмотры и оформление восстанавливаются на устройстве по правилам пака. Передаются только разрешённые факты; скрытые карты и случайные результаты остаются у хоста.","Два выбора плана в Стихийной потасовке отправляются вместе; быстрый выбор кубиков в Ятзи объединяется. Черновики переживают переподключение и не засоряют историю.","RTC14: общий бинарный формат сокращает служебные данные без сокращения SHA-256. Realtime v3 передаёт контекст линии один раз, подтверждает её хешем и восстанавливает недостающие точки. Участникам нужна одинаковая версия приложения и новые паки."]},{"version":"0.21.0-preview.59","changes":["Общий сетевой ход содержит тип действия и исходные ID выбранных компонентов. Таблица всех сочетаний ходов для кодирования не нужна; автор определяется по соединению.","ID команды для безопасных повторов сохранён. Контекст сеанса передаётся один раз, хост проверяет действие по правилам и подтверждает после сохранения. RTC13: используйте одинаковую версию приложения."]},{"version":"0.21.0-preview.58","changes":["Действия всех игр используют общий сетевой формат: короткий ID разрешённого выбора вместо повторной передачи команды. Автор определяется по соединению; проверка, сохранение и ACK остаются у хоста.","Сетевые изменения кодируются короткими операциями с общими префиксами путей; меньше повторяющихся служебных полей.","Полная SHA-256 проверка состояния и цепочки событий сохранена. RTC 12: участники используют одинаковую версию приложения."]},{"version":"0.21.0-preview.57","changes":["Возврат в приложение или восстановление канала во время проверки связи сразу запускает одну актуальную проверку, без ожидания очередного таймера.","Повторные проверки объединяются; запрос восстановления на том же соединении использует уже идущий status вместо дополнительного RPC."]},{"version":"0.21.0-preview.56","changes":["Повторный ввод остаётся заблокирован до получения состояния подтверждённого хода; ранний ACK не может привести к потере второго действия."]},{"version":"0.21.0-preview.55","changes":["Меньше сетевых данных: компактные разрешённые кадры и изменения массивов, кеш неизменяемых фактов.","Подтверждение сохранённого хода не ждёт рассылки; история загружается диапазонами, повторные запросы восстановления объединяются.","Крупные RTC-сообщения и Realtime-превью передаются двоичными пакетами без base64; подключайтесь с одинаковой версией приложения.","Облачные уведомления проверяют активность без построения игровых сцен; очередь хранит только последнее ожидающее состояние."]},{"version":"0.21.0-preview.54","changes":["Горизонтальная компоновка сначала резервирует читаемые карточки игроков и руку с управлением, затем отдаёт оставшееся место полю.","На узком экране соперники располагаются в одной колонке; две колонки включаются только при достаточной ширине. Поворот и обновления партии сохраняют устойчивую геометрию."]},{"version":"0.21.0-preview.53","changes":["Краткие сбои проходят без текста на игровом поле; длительное отключение отмечается серой карточкой и значком разрыва, возврат — спокойной подсветкой.","Обмен приглашениями Online переживает краткие ошибки HTTP с ограниченными повторами сигнальных запросов. Игровые действия этим механизмом не повторяются.","Проверены максимальные составы всех 13 сетевых паков через Рядом и настоящий Online: разрывы, возвращение, задержки, дубли и потеря обновления."]},{"version":"0.21.0-preview.52","changes":["Общая проверка подключённых участников Supabase за один запрос, версии метаданных чата и ограниченный кеш истории.","Realtime SDK: незавершённые штрихи, частичное стирание, проверка подписей и восстановление; приватные точные и близкие ответы с подтверждением ведущим."]},{"version":"0.21.0-preview.51","changes":["Сетевой этап 5: ограниченная очередь control/state/bulk, сборка крупных сообщений из частей до 16 KiB, backpressure и ограничения незавершённых сообщений. Передача хоста использует общую очередь.","Исправлено ожидание асинхронной авторизации status: соединение и экран результатов не переходят в ложное состояние «нет связи». Панель чата возвращает фокус редактору после предложения хоста."]},{"version":"0.21.0-preview.50","changes":["Сетевой этап 4: клиент строит сцены, промежуточные кадры, звуки и эффекты из разрешённой модели всех 15 паков. Команды передаются один раз с индексами ссылок.","Небольшие изменения модели передаются patch; checkpoint восстанавливает разрывы. SHA-256 проверяет позицию, управление и цепочку видимых событий. RTC transport 8."]},{"version":"0.21.0-preview.49","changes":["Стихийная потасовка .22 сохраняет место руки при возрождении и выборе добычи, включая повторное открытие и поворот экрана.","Общий движок освобождает ограничения высоты действий при переиспользовании DOM-узла для руки."]},{"version":"0.21.0-preview.48","changes":["Сетевой этап 3 (CPU): кеширование неизменяемых проекций и восстановленного оформления; хост не вычисляет звук и эффекты для сетевого ответа. RTC transport 6, отдельная ревизия имён игроков."]},{"version":"0.21.0-preview.47","changes":["Сетевой этап 2: новые события вместо полного журнала, восстановление пропусков, диапазонная история с общим пулом событий, атомарные пакетные записи и кеш до 16 MiB. RTC transport 5."]},{"version":"0.21.0-preview.46","changes":["Сетевой этап 1: короткая проверка связи вместо полного состояния, один push на команду без дублирования в ACK, раннее отбрасывание повторов и единый writer истории. RTC transport 4."]},{"version":"0.21.0-preview.45","changes":["Жетон количества карт сохраняет постоянные пропорции карты 5:7: для нескольких цифр уменьшается шрифт.","История сетевой партии читается из памяти и локального архива. У хоста запрашиваются только отсутствующие кадры, параллельные запросы одного кадра объединяются.","Сетевые события передаются компактными фактами: оформление, звуки и перемещения восстанавливаются локально из пака. Удалены производные списки эффектов и повтор списка событий."]},{"version":"0.21.0-preview.44","changes":["Счётчик карт в карточке игрока расширяется по числу цифр: двузначные и трёхзначные значения помещаются с отступами, высота жетона сохранена."]},{"version":"0.21.0-preview.43","changes":["Передача хода анимирует исходные карточки игроков без копирования DOM. Рука сохраняет свои размеры, перекрытие и расположение; отмена и замена узла не оставляют визуальных копий."]},{"version":"0.21.0-preview.42","changes":["Исправлена компоновка карточек игроков во время передачи хода: слой анимаций сохраняет позиции аватара, имени, счётчиков и руки в исходной сетке."]},{"version":"0.21.0-preview.41","changes":["Общие подсказки игроков поддерживают мигающий предпросмотр положительного и отрицательного эффекта. UNO .14 использует их для пропуска, разворота и +2/+4.","Передача хода стала заметнее: отдающая карточка слегка сжимается, принимающая увеличивается на 7%. Анимация входит в общую очередь показа и учитывает уменьшение движения."]},{"version":"0.21.0-preview.40","changes":["Чат лобби открывается выдвижной панелью, как в игре, без отдельного меню обновления.","Краткие правила читаются сверху вниз в обеих ориентациях. В UNO .13 круглые значки выбора цвета и однострочные примеры альтернатив в правилах."]},{"version":"0.21.0-preview.39","changes":["Синяя подсветка следующего игрока удерживается вместе с текущим ходом до завершения анимации. При перерисовке и отмене показа обе подсветки остаются синхронными."]},{"version":"0.21.0-preview.38","changes":["Лобби и результаты перекомпонованы в столбцы для низкого горизонтального экрана. Жетоны очков ниже.","Поддержана синяя подсветка следующего игрока UNO, включая предварительный выбор карты смены направления (обновите пак UNO)."]},{"version":"0.21.0-preview.37","changes":["Убран переключатель области у камеры. Приложение автоматически учитывает безопасные отступы, сообщаемые браузером; старое значение переключателя больше не влияет на раскладку."]},{"version":"0.21.0-preview.36","changes":["Горизонтальные экраны приведены к общей сетке: аккаунт без вложенных колонок, связанные настройки сгруппированы, строки уведомлений выровнены.","В «Играх» боковые вкладки и единые границы карточек и удаления. Сводки «Данных» компактнее; удаление на устройстве и в облаке остаётся на одном уровне."]},{"version":"0.21.0-preview.35","changes":["На широких низких экранах вкладки настроек, оформления и данных перенесены в левую колонку. Формы аккаунта и имени ограничены по ширине, настройки и уведомления используют два столбца.","Пояснение области у камеры перенесено в иконку справки. Фон остаётся до краёв экрана; безопасные отступы учитывают обычные и максимальные значения браузера. Если браузер сообщает нули, справка поясняет отсутствие видимого эффекта."]},{"version":"0.21.0-preview.34","changes":["В «Настройки → Поведение» добавлена опция «Использовать область у камеры». Безопасные отступы применяются одинаково в обеих ориентациях и fullscreen.","Фон запуска, fullscreen и стандартного PWA-манифеста согласован со светлой темой; сохранённая тёмная тема учитывается до загрузки интерфейса."]},{"version":"0.21.0-preview.33","changes":["Уменьшены лишние отступы игрового экрана и карточек. Верхние системные блоки выровнены с подложкой зон.","Список оппонентов использует доступную высоту без зазоров пустых строк. Полноэкранный режим сохраняет место для жетонов, а при настоящем переполнении список прокручивается."]},{"version":"0.21.0-preview.32","changes":["Кнопка импорта расположена слева от обновления в быстрых действиях «Данные → Устройство» и обеих вкладок «Игр»."]},{"version":"0.21.0-preview.31","changes":["На вкладках «Устройство» и «Облако» выровнены полосы занятого места, общий формат объёма и положение удаления всех сохранений. Сводка устройства использует одноцветный значок ХОД."]},{"version":"0.21.0-preview.30","changes":["В менеджере игр обновление и импорт вынесены в быстрые действия заголовка. Удаление открыто без спойлера, переход «Данные и облако» убран.","На экране обновлений убрана кнопка справки.","На главном экране сохранено место для тени последнего ряда карточек во всех видах каталога.","Размер подписей вкладок в настройках и общении приведён к «Моим партиям»."]},{"version":"0.21.0-preview.29","changes":["Экраны данных стали компактнее: обновление и импорт вынесены в быстрые действия, удаление расположено перед сохранениями. Оба списка открыты и оформлены одинаково, лишние пояснения убраны."]},{"version":"0.21.0-preview.28","changes":["Убран пустой блок действий после потери руки в Стихийной потасовке: он добавлял лишний зазор и вызывал прокрутку пустой зоны.","Карты общей сводки Стихийной потасовки имеют тот же размер, что и на фазовых экранах. Общий крупный показ использует всю область поля, сохраняя размер карт и кубиков."]},{"version":"0.21.0-preview.27","changes":["Перед каждым ходом Стихийной потасовки показаны все выбранные карты: движения и атаки сгруппированы по стихиям в порядке применения. Общий экран показан вдвое дольше фазового.","История пропускает промежуточные готовности игроков и сразу переходит к публичному раскрытию; игровые события сохранены."]},{"version":"0.21.0-preview.26","changes":["Публичные раунды показываются по очереди: новые действия ботов больше не отменяют ещё не показанные урон, потерю жизни и другие эффекты после выбывания игрока.","Восстановленная история достраивается только новыми действиями: старые ходы не пересчитываются заново при каждом обращении.","Поворот карт Стихийной потасовки применяется сразу, без плавного доворота."]},{"version":"0.21.0-preview.25","changes":["Во вкладке «Доступно» появилась кнопка «Установить все»: она загружает только отсутствующие игры, показывает ход установки и позволяет повторить неудачные загрузки.","На приветственном экране предложена установка приложения ХОД, а загрузка всех игр выбрана по умолчанию. Отметку можно снять и выбрать игры отдельно."]},{"version":"0.21.0-preview.24","changes":["Кнопка «Проверить обновления» пересобирает «Доступно»: уже установленные игры исчезают из этого списка и остаются в «Установлено». Сразу после установки карточка сохраняет своё место до обновления списка."]},{"version":"0.21.0-preview.23","changes":["Игры устанавливаются прямо в компактной карточке «Доступно»: прогресс и результат остаются на месте, без перехода на экран обновления. Описание игры и изменения последней версии показаны отдельно.","На экране обновления кнопка «Очистить» скрыта, если старых версий нет. После успешной очистки окно закрывается."]},{"version":"0.21.0-preview.22","changes":["После удаления всех игр экраны «Мои партии», «Общение» и «Параметры» остаются на месте: их компоновка больше не зависит от стилей пака.","Проверка обновлений обращается к серверу даже при ошибочном системном признаке «нет сети». Настоящие ошибки соединения остаются видимыми, проверку можно повторить."]},{"version":"0.21.0-preview.21","changes":["Приложение больше не содержит встроенную коллекцию игр. Установите нужные игры через «Доступно»; уже установленные версии и партии остаются на устройстве.","В preview подключён каталог скачивания игр. Ошибки проверки игр и приложения показываются отдельно; доступное обновление приложения можно подготовить независимо от каталога."]},{"version":"0.21.0-preview.20","changes":["Установленные игры хранятся компактнее: сжатая запись сохраняет все версии паков, выбранные настройки и резервные данные.","Сохранение паков остаётся атомарным: ошибка или отмена не заменяет прежнюю запись. Экспорт резервной копии получает полные данные."]},{"version":"0.21.0-preview.19","changes":["Чат комнаты открывается из меню партии с обычной анимацией интерфейса; черновик сохраняется при закрытии и повторном открытии.","В правилах из сетевой партии работают вкладки «Кратко / Полные правила», клавиатурное переключение и оглавление. Возврат восстанавливает меню партии.","Возврат в окно сетевой партии и открытие локального сохранения сразу показывают текущий кадр. Старый раунд не проигрывается повторно; новые раунды и явный просмотр истории продолжают работать."]},{"version":"0.21.0-preview.18","changes":["Экран «Данные» больше не восстанавливает всю историю сетевой партии для размера файла или выгрузки: экспортируется журнал команд с проверяемым конечным состоянием. Проверка воспроизведения остаётся на импорте.","Сценарий публичного раунда владеет своим переходом: устранены лишний общий сигнал и параллельная анимация перед раскрытием планов.","В Стихийной потасовке первое действие отмечено одинаковым круглым жетоном на карте и в верхнем левом углу переключателя типа."]},{"version":"0.21.0-preview.17","changes":["В горизонтальной раскладке соперники по умолчанию размещаются в двух столбцах; длинный список прокручивается отдельно от поля и собственной карточки.","Исправлены размер и центрирование избранного, отступы подписей каталога и положение полос прокрутки. Тип партии в «Моих партиях» показан тем же бейджем, что в недавней игре.","Возврат кнопкой, браузерным Back и свайпом панели озвучивается после закрытия, без повторного сигнала.","Сетевое сохранение хранит комнату, начальное состояние, команды и последний checkpoint. Возобновление не проигрывает всю историю; история восстанавливается по запросу.","Старые нативные сетевые сохранения прежних preview не возобновляются. Старые записи автоматически не удаляются.","В Стихийной потасовке убрана повторная подсказка очередности под рукой; информация остаётся в памятке. Вычислимые кадры анимации не дублируются в checkpoint."]},{"version":"0.21.0-preview.16","changes":["Движок переиспользует неизменившиеся компоненты по физическим ключам. При выборе и повороте обновляются изменённые фрагменты вместо повторного разбора всего поля.","Восстановлены и увеличены значки ботов и hotseat на аватарках. Сетевое присутствие больше не перерисовывает аватарки.","Перед обновлением под сворачиваемым блоком доступны изменения встроенных паков, в том числе при недоступном каталоге.","Исправлены привязка жетонов к аватаркам и учёт параметров пака в списке партий: первый игрок скрыт в Стихиях, команды Лудо остаются у своих участников.","Из меню партии можно остановить незавершённую игру и перенести её в историю, затем продолжить. Завершённые игры открывают результаты с возвратом через историю на исходный экран.","Удаление сохранения защищает только выбранную текущую партию; другая активная игра не блокирует удаление остановленной.","На устройстве показаны размеры файлов и отдельные действия экспорта/удаления. Облачная синхронизация использует тот же ID и не создаёт повторные локальные копии."]},{"version":"0.21.0-preview.15","changes":["Промежуточные решения в окне планирования остаются в памяти. Полное подтверждение хода записывает накопленные шаги и квитанции одной транзакцией.","Сетевая история хранит изменения состояний без повторных копий кадров. Старые журналы уплотняются в фоне при возобновлении; все ходы сохраняются.","Локальный поворот больше не разбирает поле дважды. Закрытие панели не отправляет ложное изменение настроек и не отменяет анимации игры.","Исправлены цвета всех схем памятки. В разделе данных пояснена разница между внутренней историей и сжатым экспортом."]},{"version":"0.21.0-preview.14","changes":["Кадры публичного раунда готовятся по одному: следующий кадр строится в свободный промежуток текущей анимации. В DOM больше не сериализуется весь раунд при каждом обновлении.","Промежуточная готовность в одном окне решений не вызывает подгрузку всех исторических снимков. История ходов сохраняется полностью.","Для закрытых решений убрано ненужное измерение движущихся объектов; чтение геометрии карточек игроков сгруппировано перед обновлением DOM.","Запись хода явно запускает коммит IndexedDB, без лишнего цикла автокоммита; подтверждение отправляется после полного завершения транзакции."]},{"version":"0.21.0-preview.13","changes":["Общий цикл действий SDK: ожидание ответа и повторный ACK больше не перерисовывают поле; история, права и независимые реакции сохраняют свои ограничения.","Убраны повторные копии авторизованных снимков, проверки неизменяемых позиций и обходы отсутствующих механик; сведения об игроках собираются один раз на отображение.","Текущий публичный кадр сохраняет свои элементы при обновлении оболочки; повторная установка скорости не прерывает анимацию. Проверены первые действия всех 15 игр."]},{"version":"0.21.0-preview.12","changes":["Убраны повторные принудительные пересчёты SVG-поля при выборе действий и ходе ботов: геометрия окна переиспользуется до изменения размеров или масштаба.","Обновление карточек не переписывает неизменившиеся атрибуты; анимации поля и игроков измеряются совместно после обновления DOM.","После публичного показа раунда накопившиеся статусы готовности ботов объединяются в актуальное отображение; все ходы и события сохраняются в истории."]},{"version":"0.21.0-preview.11","changes":["Хост отмечен золотой рамкой вокруг аватара. Корона хоста убрана из карточек; сам значок сохранён в библиотеке.","Дополнительные игроки hotseat отмечены крупной ладонью в аватаре. Основной игрок сохраняет выбранный аватар."]},{"version":"0.21.0-preview.10","changes":["В вертикальной стандартной рассадке карточки оппонентов расположены в три столбца; имя и счётчики остаются справа от аватара в двух строках.","Корона хоста чёрная; жёлтый бейдж ульты в Стихийной потасовке перенесён к нижнему краю аватара."]},{"version":"0.21.0-preview.9","changes":["Во всех стандартных карточках имя и счётчики стоят справа от аватара в двух строках с одинаковыми отступами.","В Стихийной потасовке жизни и здоровье перенесены к числу карт; убийства показаны только в результатах.","Тип бота показан крупным значком в аватаре, хост отмечен наклонённой цветной короной; значки перед именами убраны."]},{"version":"0.21.0-preview.8","changes":["У значков типов игроков убраны прозрачные поля SVG; строка имени выравнивается по видимому рисунку.","В настройках до установки показана полная сводка изменений приложения и карточки паков на обычном фоне."]},{"version":"0.21.0-preview.7","changes":["Единая геометрия карточек игроков с рукой и без руки; увеличены счётчики и исправлено их обрезание.","Собственная карточка в landscape расположена внизу, быстрые действия — над ней.","Исправлены счётчики Домино, колода Дурака, зоны пасьянсов и карточки флотов Морского боя.","Устранены конкурирующие правила компоновки; ограниченные переопределения отдельных зон объявляются в паках.","Галерея содержит только шесть основных вариантов S23, без Chrome со скрытой строкой."]},{"version":"0.21.0-preview.6","changes":["Стихийная потасовка: компактная горизонтальная строка поворота и типов действий, включая ульту; памятка под рукой не обрезается.","Чат комнаты перенесён в общую панель быстрых кнопок в обеих ориентациях.","Исправлены отступы и выравнивание счётчиков, имён и значков типов игроков.","Потасовка: компактная памятка с порядком действий и таблицей стихий. UNO: изображения карт в справке."]},{"version":"0.21.0-preview.5","changes":["Системные зоны выделены рамками; кнопки имеют одинаковый размер в обеих ориентациях.","Уменьшены счётчики в карточках игроков, уточнено положение кнопки чата.","Исправлено центрирование точек на фишках; уточнены зоны и счётчики пасьянсов.","В горизонтальном режиме карточки выровнены сверху; Морской бой сохраняет нижнее положение, Лудо — привязку к базам.","Рука размещена рядом с карточкой игрока; убраны подложки действий. Кубики Лудо центрированы в зоне под синей базой."]},{"version":"0.21.0-preview.4","changes":["Возвращены прежние размер и начертание букв в аватарках игроков."]},{"version":"0.21.0-preview.3","changes":["Начало общего SDK расположений: размеры боковых зон и центрального поля не зависят от числа игроков.","Статус перенесён под название; убран индикатор хода, кнопка чата уменьшена и перемещена вправо вниз.","Первая итерация по комментариям к галерее S23; визуальная приёмка продолжается."]},{"version":"0.21.0-preview.2","changes":["После обновления показан список изменений и предложена очистка неиспользуемых старых и несовместимых паков. Используемые сохранениями версии защищены.","Обновления игр показаны карточками с обложкой и сводкой изменений каждой игры.","Диагностика находится в разделе «Поведение» под сворачиваемым блоком; выход из аккаунта расположен после восстановления пароля.","История явно обозначена заголовком «История партии». Жетон первого хода перемещается без удержания, возвращение в его поле включает «По правилам».","Жетон перенесён в строку «Игроки»; убраны пояснения о переносе и общая подпись условий автостарта.","В сетевой игре чат доступен из меню и компактной накладной кнопки; статус и действия в альбомном режиме расположены над рукой.","Альбомная шапка и действия компактнее, обложка крупнее; карточкам оппонентов выделено больше ширины.","Косынка использует правую альбомную колонку для домов, сброса, колоды и действий; в Пауке доступна отмена добора.","Стихийная потасовка воспроизводит фазы на одном сохраняемом поле; уменьшено создание скрытой разметки при выборе карт и переходах раунда."]},{"version":"0.21.0-preview.1","changes":["Переработаны навигация, лобби, аккаунт, настройки и общение: единые экраны и панели, спокойные строки действий и понятные состояния.","Каталог поддерживает компактные строки и квадратные карточки, избранное, скрытие и редактирование порядка перетаскиванием.","Карточки партий сразу показывают статус, режим, комнату и участников; дополнительные действия открываются поверх без сдвига карточки.","Все места лобби видны с номерами и цветами; параметры игры открыты в группах «Порядок игры», «Параметры», «Завершение».","Для всех 15 игр подготовлены короткие иллюстрированные правила; полные правила доступны отдельно.","Обновление общения сохраняет положение списка и ввод; исправлены призраки переноса, выравнивания, системная прокрутка и поворот игровой раскладки.","Установка ХОД встроена в профиль; на iPhone показаны системные шаги добавления на домашний экран."]},{"version":"0.20.1-preview.3","changes":["В онлайн-комнатах подключены STUN и временный TURN Cloudflare: браузер автоматически проверяет доступные маршруты.","Во время подключения видны способы соединения; успешный способ отмечается галочкой перед переходом в комнату.","Для проверки соединений временно включён закрытый диагностический журнал с очисткой через 48 часов — без IP, SDP, токенов и состояния партии."]},{"version":"0.20.1-preview.2","changes":["На iPhone восстановлена прокрутка главных экранов после кнопки полноэкранного режима.","Повторный ответ QR/звукового приглашения обрабатывается один раз; исправлена ошибка WebRTC «wrong state: stable».","Ожидание соединения ограничено по времени, включая этап до создания канала; обрыв и закрытие прерывают ожидание."]},{"version":"0.20.1-preview.1","changes":["При регистрации обязательно уникальное имя аккаунта; оно сохраняется вместе с созданием аккаунта.","Ошибки лимита писем и ожидания ответа сервиса показаны отдельно, форма сохраняет введённые данные.","Уведомления о заявке в друзья и её принятии появляются внутри приложения; Push открывает окно участника."]},{"version":"0.20.0","changes":["Сетевые аккаунты, друзья, личные и групповые чаты, приглашения и Web Push с переходом к нужному сообщению.","Онлайн-комнаты: добровольная передача хоста в лобби и партии, управление участниками, временные боты, автозапуск при выполнении условий и очистка закрытых комнат.","Облачные сохранения, синхронизация аккаунта и перенос сохранений с сохранением границ доступа к истории и игровым данным.","Улучшены масштабирование, прокрутка, шапка, карточки игр на iPhone и установка обновлений PWA."]},{"version":"0.20.0-preview.54","changes":["Исправлены исчезающие карточки игр на iPhone: WebKit больше не сжимает их до точек."]},{"version":"0.20.0-preview.53","changes":["Исправлена доставка результата партии после передачи хоста зрителю или Столу: последнее состояние приходит перед возвратом комнаты в лобби, даже при асинхронной проверке доступа."]},{"version":"0.20.0-preview.52","changes":["Исправлён возврат прежнего хоста-зрителя или Стола после передачи управления во время партии: для этих ролей место игрока не требуется.","Проверен полный круг передачи хоста туда и обратно с сохранением ролей, мест и состояния партии."]},{"version":"0.20.0-preview.51","changes":["Окно участника открывается сразу с готовым набором действий: кнопки не появляются позже и не сдвигаются.","Передать хоста во время партии можно подключённому игроку, зрителю или Столу. Пока получатель отвечает, отправитель продолжает играть; решение приходит уведомлением сверху.","Управление игроками перенесено из отдельного окна настроек в окна участников лобби: отойти, вернуться и подключить временного бота.","Исправлено закрытие Онлайн-комнаты после смены хоста, когда новый владелец ещё не открывал окно приглашений."]},{"version":"0.20.0-preview.50","changes":["После установки приложение самостоятельно проверяет активацию обновления и перезагружается, даже если мобильный браузер пропустил событие смены Service Worker.","Текст уведомления об обновлении расположен внутри прокручиваемой области окна и не перекрывается заголовком."]},{"version":"0.20.0-preview.49","changes":["После закрытия Онлайн-комнаты автоматически удаляются временные подключения, передачи хоста и ожидающие уведомления. История чатов и партий сохраняется.","Закрытая комната снимается с подключённых устройств и перестаёт переподключаться.","Передача хоста обозначена короной со стрелкой от неё.","«Ваш ход», начало и завершение партии не показываются системным Push, пока открыт экран этой партии; в фоне уведомления сохраняются."]},{"version":"0.20.0-preview.39","changes":["Шапка библиотеки закреплена относительно экрана без зависимости от прокрутки. Исправлено положение в полноэкранном режиме: она занимает освободившийся верх, а при выходе возвращается обратно; фон закрывает область над содержимым."]},{"version":"0.20.0-preview.38","changes":["Общая шапка с логотипом и быстрыми действиями закреплена при прокрутке «Все игры» и «Мои партии». Сохранены компактные кнопки, масштаб, фон темы и позиции страниц."]},{"version":"0.20.0-preview.37","changes":["Исправлена повторная потеря прокрутки после открытия менеджера паков или настроек: общий обработчик закрытия больше не фокусирует устаревшую кнопку при переключении страниц. Возврат фокуса в окна выполняется без прокрутки."]},{"version":"0.20.0-preview.36","changes":["Исправлен сброс прокрутки при переключении «Все игры» / «Мои партии»: служебные переходы кнопки «Назад» больше не подменяют позиции страниц прокруткой из браузерной истории."]},{"version":"0.20.0-preview.35","changes":["Компактные кнопки включаются по доступной ширине после масштабирования: настройки, правила, лобби и главный экран помещаются при 110–120%. При возврате масштаба восстанавливаются обычные кнопки.","Исправлены обрезание колонок лобби и выравнивание действий. Из поля имени убрана пустая колонка старой кнопки сохранения; центры и края сохраняются после zoom."]},{"version":"0.20.0-preview.34","changes":["Групповые приглашения в игру доступны каждому участнику до закрытия комнаты; отклонение убрано, повторный вход после выхода разрешён.","В группе добавлена включённая по умолчанию опция «Показывать историю новым»; скрытая история фильтруется сервером.","В чатах появились переходы к ближайшим активным приглашениям сверху и снизу и кнопка прокрутки к последнему сообщению. Позиция чтения сохраняется при новых сообщениях и повторном открытии."]},{"version":"0.20.0-preview.33","changes":["Вход в Онлайн-комнату обходится без дополнительного последовательного запроса привязки личности; новые предложения соединения обрабатываются раньше фоновых проверок.","Обработанные SDP больше не пересылаются повторно при опросе хоста; завершённые сигналы не вызывают учащённый опрос. Поддержка прежних клиентов сохранена.","Повторно проверены завершение и история, возврат в лобби, роли хоста, готовность, замены состава, обрывы и восстановление на локальных WebRTC-клиентах."]},{"version":"0.20.0-preview.32","changes":["Исправлен учёт Онлайн-комнат: зависшие записи и старое членство не занимают активное место аккаунта; восстановление комнаты сохраняется.","При ошибке приглашения убирается ожидание и доступна кнопка повторения. Облачный rendezvous доступен только Онлайн-комнатам.","Отключённый RTC больше не продлевает активность участника в облаке; старые тестовые подключения корректно освобождают место."]},{"version":"0.20.0-preview.31","changes":["Окно «Удалить все партии»: короткие кнопки «Облако» и «Устройство», уменьшенные боковые отступы для узких экранов."]},{"version":"0.20.0-preview.30","changes":["Верхняя часть «Моих партий» оформлена как главный экран: «Мои партии / Истории игр», импорт справа, общие фильтры и компактная строка количества.","Добавлено удаление всех облачных сохранений отдельно от локальных партий, с подтверждением и защитой от повторной автоматической загрузки."]},{"version":"0.20.0-preview.29","changes":["После успешной активации обновления добавлен резервный автоматический переход на новую версию, если окно не обработало смену Service Worker.","Резервный переход касается только ранее проверенных свободных окон ХОД; уже перезагрузившиеся окна и посторонние приложения не затрагиваются."]},{"version":"0.20.0-preview.28","changes":["Группы показаны рядом с друзьями в общем списке отправки приглашений в игру, с такой же кнопкой приглашения.","Число участников обновляется в открытом групповом чате и профиле из фоновой синхронизации; возврат из других окон больше не восстанавливает старый счётчик.","После возврата из поиска друзей список перечитывается в фоне, сохраняя мгновенный показ кеша."]},{"version":"0.20.0-preview.27","changes":["Кнопка обновления открывает окно из главного меню даже при активной комнате; загрузка обновления доступна без выхода.","Установка по-прежнему защищена: при активной комнате показано понятное сообщение о сохранении партии и выходе; автоматическое окно не прерывает комнату."]},{"version":"0.20.0-preview.26","changes":["Убраны подписи «Руки скрыты» и «Руки открыты» из строки состояния локальных и сетевых партий."]},{"version":"0.20.0-preview.25","changes":["Исправлен неработающий экран истории после закрытия лобби: уничтоженное игровое представление больше не остаётся на фоне, открывается рабочий главный экран.","При включённом автозапуске хост-зритель и хост-стол автоматически переводят завершённую комнату в следующее лобби.","Игрок может подтвердить готовность следующей партии, пока хост ещё смотрит завершённую; отметка передаётся после открытия лобби с проверкой конфигурации.","В тёмной теме доступные элементы выделяются непрозрачным жёлтым контуром с тёмной обводкой на светлых фигурах. Надпись «Автозапуск» выровнена по центру кнопки."]},{"version":"0.20.0-preview.24","changes":["Готовность можно отметить без связи с хостом: она передаётся после восстановления только для прежней конфигурации партии.","У хоста добавлен «Авто»: готовность всех игроков запускает обычный отсчёт. Игроки видят рядом с готовностью надпись «Автозапуск».","В отсчёте появилась кнопка «Я не готов!»: запуск отменяется, все остаются в лобби, готовность снимается только у нажавшего.","Запоздавшие ответы команд и проверки связи не откатывают состояние лобби; после закрытия заменённого игрового окна освобождается блокировка ввода."]},{"version":"0.20.0-preview.23","changes":["Обновления переиспользуют файлы предыдущих версий по SHA256: скачиваются только новые и изменившиеся файлы.","Можно пропускать версии и продолжать частично загруженное обновление: полный комплект целевой версии собирается из проверенных файлов нескольких кешей.","Прогресс показывает только сетевую загрузку; установка повторно проверяет весь комплект и сохраняет пользовательские данные.","Проверка обновлений обнаруживает более новую сборку даже при наличии ожидающего обновления; запоздавшие ответы старого кандидата игнорируются."]},{"version":"0.20.0-preview.22","changes":["Списки комнат учитывают срок активности хоста в Supabase: после его истечения комната недоступна для нового входа и не показывается в каталоге.","Комната, пароль и места сохраняются для восстановления; истечение активности не закрывает партию и не обрывает работающий WebRTC.","Членство и открытые комнаты обновляются параллельно одним агрегированным запросом; устаревшие записи фильтруются и из кеша."]},{"version":"0.20.0-preview.21","changes":["Исправлен повторный вход облачного игрока в зарезервированное место без локального resume-токена: доверенная серверная привязка восстанавливает того же участника и выдаёт новый токен.","Обычный ввод имени/ID не даёт права занять чужое место; активное соединение не перехватывается.","Списки друзей, чатов и групп прогружаются фоново вместе с синхронизацией аккаунта, сохраняются раздельно по аккаунтам и сразу показываются при открытии.","Добровольный выход из завершённой партии освобождает место без попытки приостановить уже законченную Session."]},{"version":"0.20.0-preview.20","changes":["В промежуточном лобби завершённой партии готовность игроков отображается снятой, даже пока хост ещё не вернулся.","В поле номера комнаты добавлен неснимаемый префикс #; вставка номера с # и ссылки поддерживается."]},{"version":"0.20.0-preview.19","changes":["Пароль комнаты вводится в шести визуальных ячейках: заглавные буквы, моноширинный шрифт хоста и строгий лимит шесть символов.","Работают выбор ячейки, стрелки, Backspace/Delete, выделение, двойное нажатие, вставка, Enter и Tab. Ряд не растягивается на ПК, отступы окна уменьшены.","Выровнен отступ между «Рука веером» и «Три соперника» в настройках."]},{"version":"0.20.0-preview.18","changes":["Во время партии хост может удалить участника с подтверждением; добровольный выход освобождает слот, аварийный обрыв сохраняет резерв.","Замена состава приостанавливает ту же партию: игровые места, карты, очки и история сохраняются. Слот можно оставить открытым или занять ботом, закрывать его нельзя.","После изменения конфигурации игроки повторно подтверждают готовность и проходит новый отсчёт. Уведомление и плавное мигание кнопки комнаты подсказывают перейти в лобби.","Заполнение открытого места, уход замены до продолжения и настройки бота не сбрасывают готовность остальных."]},{"version":"0.20.0-preview.17","changes":["Подтверждённый выход удаляет облачное членство комнаты и локальные данные восстановления; новый вход снова проверяет пароль. Восстановление после обрыва остаётся доступным участникам.","В менеджере паков общий объём устройства расположен слева, облако справа; иконки и значения окрашены в цвета соответствующих полос."]},{"version":"0.20.0-preview.16","changes":["Возврат в завершённую сетевую комнату открывает лобби; восстановление связи больше не открывает старую завершённую партию поверх ожидания лобби.","Во время онлайн-подключения начальный опрос ускорен до 0,5 секунды; обычный фоновый интервал хоста сохранён."]},{"version":"0.20.0-preview.15","changes":["В завершённой Сетевой и Онлайн партии доступны только «История» и «В комнату»; выход выполняется из лобби.","Все реакции приведены к прозрачному WebP 256×256; размер приложения уменьшен.","Пароль комнаты отображается заглавными при вводе и вставке; кнопка приветствия обновляется после входа в аккаунт."]},{"version":"0.20.0-preview.14","changes":["Обновление обнаруживается до скачивания файлов приложения. Загрузка начинается по отдельной кнопке и показывает прогресс.","Окно можно закрыть: загрузка продолжается, кнопка на главном экране показывает доступность, загрузку, ошибку или готовность установки.","После обрыва можно продолжить с проверенных файлов. Причина ошибки видна в окне; установка запускается отдельно и сохраняет прежние проверки открытых партий."]},{"version":"0.20.0-preview.13","changes":["Справка у выбранных параметров правил, компактные настройки и чекбокс «Рука веером».","Мгновенное переключение светлой и чёрной темы; чёрная загрузка PWA, аватары-персонажи.","Компактные окна аккаунта и сохранения, облачная квота и упорядоченные действия паков.","Общая синхронизация аккаунта, правильные возвраты из окон и метаданные старых историй.","Выход, сброс, удаление и ручные облачные операции требуют понятного подтверждения."]},{"version":"0.20.0-preview.12","changes":["Облачные сохранения: настройка аккаунта, отправка после завершения партии и при выходе в меню, отдельное управление каждой историей.","Лимит 10 МБ на аккаунт проверяется сервером. В менеджере паков появился отдельный облачный счётчик.","Облачные действия и экспорт в файл объединены в одном окне. Новые иконки документа со стрелкой для импорта и экспорта; защита от конфликтов и потери связи."]},{"version":"0.20.0-preview.11","changes":["Исправлено разрастание сетевых сохранений: повторяющиеся события хранятся один раз, история ходов сохраняется полностью.","Старые архивы читаются и уплотняются при открытии; новые экспортируются в компактном формате.","Обычный экспорт использует установленный пак. Для автономного переноса пак можно включить отдельно; файлы истории дополнительно сжимаются."]},{"version":"0.20.0-preview.10","changes":["В правилах появились оглавление и быстрые переходы. Название окна — «Правила», варианты настроек оформлены одинаково во всех играх.","Сохранённая тема применяется с начала загрузки и передаётся манифесту PWA. Android обновляет установленную заставку по собственному расписанию.","Исправлены личные приглашения после групповых, исчезающая кнопка комнаты у гостя и зависающие баннеры сообщений. Добавлен необязательный Markdown для авторов новых паков."]},{"version":"0.20.0-preview.9","changes":["Игровой RTC больше не ждёт Supabase на каждый ход и кадр. Временный сбой API не разрывает проверенный канал.","Исправлены сторона анимаций штрафных карт, пустая колода UNO и выход без связи.","Явный вход восстанавливает начатую партию; сохранённая онлайн-партия помнит облачную комнату."]},{"version":"0.20.0-preview.8","changes":["Новые Push-события друзей, групп и партии: начало, продолжение, завершение и ваш ход.","Выбранные настройки показаны перед правилами; изменения хоста — всплывающим списком старых и новых значений.","Переподключение сохраняет текущий экран и чат. Убраны две кнопки комнаты и громоздкое требование нового приглашения."]},{"version":"0.20.0-preview.6","changes":["Общий локальный preview: уведомления, передача хоста, временные боты и перенос сохранений.","Исправлены смена аккаунта Push, закрытие импорта и освобождение хранилища истории.","SQL для Supabase и проверка версий RPC теперь собираются из исходных миграций. Публикация не выполнялась."]},{"version":"0.20.0-preview.5","changes":["Экспорт и импорт отдельных сохранений с точной версией пака.","Локальная копия архива хоста и перенос доступной участнику истории без ключей переподключения.","Проверка целостности, совместимости и конфликтов; существующие партии не заменяются. Локальная предварительная сборка."]},{"version":"0.20.0-preview.4","changes":["Временный бот для отошедшего или отключённого игрока по решению хоста.","Явный возврат управления с сохранением места, карт и уже принятых ходов.","Состояние подмены сохраняется при восстановлении и передаче хоста. Локальная предварительная сборка."]},{"version":"0.20.0-preview.3","changes":["Плановая передача роли хоста подключённому игроку с его согласием.","Журнал и игровые места сохраняются; участники переходят на прямые соединения с новым хостом.","Для онлайн-передачи требуется обновить SQL. Локальная предварительная сборка."]},{"version":"0.20.0-preview.2","changes":["Web Push для сообщений, приглашений в группы и в игру: явное включение на устройстве и переход в нужный чат.","Отзыв подписки при выходе, подавление повторов и уведомлений в открытом приложении.","Для фоновой доставки требуется отдельно подключить сервер Push в Supabase. Локальная предварительная сборка."]},{"version":"0.20.0-preview.1","changes":["Локальная предварительная сборка: онлайн-комнаты, друзья, группы и чаты.","Кеш сообщений, непрочитанные сообщения и приглашения, общий и командный чат.","9 авторских реакций: быстрый выбор, короткие обозначения в тексте и подсказки при удержании."]},{"version":"0.19.11","changes":["Правила всех игр стали короче: шаги, списки, таблицы и иллюстрации реальных игровых элементов и кнопок.","Объёмные фишки в Лудо, Змеях и Стихиях; улучшены рамки тайлов, выделения, меч и выбранные пункты слайдеров.","PWA при обновлении учитывает только окна ХОД, а не другие приложения на том же домене.","В Змеях и лестницах поправка ±1 допускает движение на 0–7 клеток; описания эффектов сокращены.","Подготовлены правила Стихийной потасовки редакции 1, буклет A4 и лист памяток для печати."]},{"version":"0.19.10","changes":["Исправлена пропадающая кнопка установки PWA на GitHub Pages: приглашение Chrome сохраняется до входа по паролю.","Исправлен конфликт идентификатора PWA с другими приложениями на том же домене: у ХОД отдельный постоянный ID /playroom.","Добавлены стандартные некоммерческие лицензии и отдельные условия Стихийной потасовки; лицензии включены в архивы выпуска."]},{"version":"0.19.9","changes":["Установленная PWA открывается из локального кеша без ожидания сети.","На GitHub Pages приложение после первого входа сохраняется на устройстве в расшифрованном виде; новая версия расшифровывается один раз при обновлении.","Кнопка обновлений занимает место кнопки установки PWA, с теми же оформлением и анимацией.","Менеджер паков открывается без скачка содержимого при подсчёте объёма и получении каталога.","Сортировка и избранное сохраняют статистику без повторного подсчёта; запоздалые ответы закрытого окна игнорируются."]},{"version":"0.19.8","changes":["Обновления приложения и паков показываются в общем окне вместо уведомлений сверху. Изменения всех пропущенных версий перечислены по порядку.","Окно появляется в главном меню и не прерывает партию. После закрытия список доступен по кнопке обновлений.","Исправлен порядок игр при первом запуске: он совпадает с коллекцией, редактором и менеджером паков.","В менеджере паков убраны лишние пояснения сверху; объёмы данных сохранены."]},{"version":"0.19.7","changes":["Исправлена регистрация локальных действий обучения в сетевой игре; игровые команды отмечаются после успешного ACK.","Паки и локальные сохранения перенесены в IndexedDB с проверкой миграции и атомарными записями. Общий размер данных и размер каждого пака видны в менеджере паков.","Новые локальные истории сохраняют настройки, seed и принятые команды. Снимки и события восстанавливаются закреплённой версией пака. Старые форматы сохранений совместимы; сетевые архивы не изменены.","Выделение текста запрещено в интерфейсе, кроме полей ввода и редактируемых областей.","Снят предел коллекции 20 МиБ; ограничение импорта одного пака 4 МиБ сохранено. Настройки и обучение остаются в localStorage."]},{"version":"0.19.6","changes":["Срочное обучение UNO работает во время эффектов и вне своего хода; успешное объявление сохраняется в прогрессе.","Боты получают защитное окно; отложенный ответ не блокируется ожидающим обвинением. Кнопка обвинения видна, но неактивна до истечения защиты.","Сначала сравниваются major/minor/patch; суффикс приоритетен только при одинаковой основной версии.","GitHub Pages: постоянный вход по паролю, PWA и статические обновления паков."]},{"version":"0.19.5","changes":["Постоянное обучение по действиям для каждого пользователя и пака, список освоенного, подтверждаемый сброс и подсказки по текущей ситуации.","Три сложности ботов; исправления сетевого восстановления, анимаций и поведения игр, принятые в предварительных сборках ниже.","После успешного обновления автоматически удаляются старые версии, не используемые сохранёнными партиями. При недоступном архиве сети или активной комнате версии сохраняются. Кнопка паков пульсирует при доступных обновлениях в коллекции и «Моих партиях».","Повторное освоение уже сохранённой цели обучения не вызывает лишней записи в хранилище."]},{"version":"0.19.4","changes":["Текстовые показатели результатов поддерживают дробные значения и заданную точность отображения.","Полные правила читаются по разделам и абзацам; настройки и значения текущей партии вынесены в конец за разделитель. Общая справочная сноска удалена. Единое отображение в комнате, локальной партии и сетевом столе.","В настройках партии правила перенесены в шапку вместо справки комнаты; закрытие вложенной справки возвращает в настройки.","Закрытие комнаты крестиком или системным Назад сохраняет комнату и возвращает на исходный экран, в том числе в текущую партию."]},{"version":"0.19.3","changes":["Компактные контекстные кнопки (32 px) и передача хода (до 36 px без роста карточки). Отдельная кнопка при рассадке Лудо закреплена в оболочке экрана, независимо от содержимого пака.","Общий runtime фиксирует треки, зазоры и выравнивание структурных сеток поля; изменение жетонов или топологии больше не снимает блокировку. Перерасчёт требует `allowLayoutChange: true` либо изменения viewport/масштаба.","Дурак: колода и все шесть пар занимают постоянные места с начала партии; выкладка не меняет сетку. Общий контракт запрещает перекомпоновку без явного разрешения или изменения экрана.","Автопередача выключена по умолчанию; основной игрок сохраняет предпочтение между партиями, гости — только в том же лобби, независимо от смены места.","В хотсите автопередача настраивается отдельно для каждого игрока; ручная кнопка перенесена в свою карточку (при рассадке Лудо — в угол экрана), пульсирует после завершения хода.","Рамки переносимых объектов повторяют SVG-контур; обычные объекты сохраняют скругление источника, клетки остаются прямоугольными.","Общий drag/drop: фишки Лудо и Змей и лестниц, карты Дурака; расширенные зоны сброса UNO/Дурака и примагничивание Домино.","Актуализированы текущие версии и границы опубликованного выпуска в документации."]},{"version":"0.19.2","changes":[]},{"version":"0.19.1","changes":[]},{"version":"0.19.0","changes":[]},{"version":"0.17.6","changes":["В «Морском бое» счётчик побед стоит в строке имени, а флот остаётся строкой ниже. Коллекция 0.6.5 убирает подсветку размера корабля после расстановки и из карточки соперника."]},{"version":"0.17.5","changes":["Морской бой сохраняет вручную выбранное поле при ходе другого игрока; зритель может включить автопоказ поля цели. Для выстрела действует минимальная пауза 750 мс, независимо от скорости анимаций. Перетаскиваемые корабли центрируются под пальцем; недопустимая позиция видна сразу.","Коллекция 0.6.3 содержит исправления Лудо 0.1.12 и Морского боя 0.1.6."]},{"version":"0.17.4","changes":["Главное меню сообщает о новых версиях установленных паков: закрываемое уведомление показывает число обновлений, а непросмотренные обновления отмечаются на кнопке паков при возврате в меню. После открытия списка паков тот же выпуск повторно не напоминается.","В результатах первый игрок получает тот же жетон, что в игре; с медалью жетон находится под ней, а в командной игре сохраняет цвет команды.","В результатах командной игры цветной жетон команды того же размера, что медаль места, слегка выглядывает из-под неё. Обычные результаты сохраняют один жетон места.","Круглые фишки, счётчики и медали рисуются одним SVG-диском с общей боковой гранью; у жетона первого игрока сохранён принятый шрифт, а цифра на маленьком жетоне опущена по центру лицевой части.","Строки результатов содержат аватар, тип игрока, имя и те же счётчики, что карточка во время партии; значки наград расположены веером.","Коллекция 0.6.2 добавляет библиотеку игровых ассетов и обновляет фишки Лудо, «Змей и лестниц», шашки и счётчик «Крестиков-ноликов»."]},{"version":"0.17.3","changes":["Лобби Лудо в командном режиме показывает жетоны обеих команд на местах игроков; в партии и лобби жетоны стали меньше, а командные жетоны без номера не имеют точки в центре. У первого игрока на командном диске остаётся единица.","Коллекция паков 0.6.1 обновляет Лудо до 0.1.10: крупные центрированные SVG-звёзды, стартовые SVG-треугольники и фишки по центрам кругов базы."]},{"version":"0.17.2","changes":["Жетон первого игрока получил светло-бежевую круглую фишку с контурной единицей по центру; одна форма используется в комнате и игровых карточках."]},{"version":"0.17.1","changes":["Счётчик главного меню различает показанные и скрытые игры; при фильтрации показывает число подходящих игр, а в режиме редактирования — общее число."]},{"version":"0.17.0","changes":["Защищённый каталог R2 позволяет обновить коллекцию или один пак без Pages deployment оболочки. Чистый профиль устанавливает игры из каталога; сохранения остаются привязаны к точной версии.","Главное меню получило режим перемещения игр между избранными, обычными и скрытыми; версия оболочки видна в нижнем блоке на телефоне.","Жетон первого игрока использует символ из настроек правил. Итоги игр хранят показатели и общие места при равенстве; короткий сигнал и подсветка сообщают о переходе хода.","Коллекция 0.6.0 добавляет итоговые показатели игр и публикуется отдельно от оболочки в защищённом каталоге R2."]},{"version":"0.16.3","changes":["История отмечает только действительно догруженные после переподключения ходы на слайдере.","Общие жетоны первого игрока и команд показываются на аватарах; таблица Ятзи сохраняет жест и прокрутку.","Игровые реплики показываются на карточках игроков; подготовка флота и анимация закрытия карт улучшены.","Коллекция 0.5.4: в Лудо видны все фишки на общей клетке, выделены безопасные звёзды и не повторяется бросок соперника при смене хода."]},{"version":"0.16.2","changes":["Во всех игровых сценах долгий тап не выделяет текст и обозначения поля. Поля ввода остаются доступными для редактирования.","Коллекция 0.5.2 обновляет Лудо до 0.1.6: синие и жёлтые фишки, базы и дорожки соответствуют цветам игроков.","В истории показаны значения кубиков Лудо и Ятзи без доступных действий. Четыре индикатора флота соперника в Морском бое помещаются в один ряд на телефоне.","Пексесо 0.1.4 закрывает несовпавшую пару перед началом следующего хода.","В «Рыбе» подсветка запроса сохраняет заданную длительность, чтобы действие было видно при обычной скорости анимации."]},{"version":"0.16.1","changes":["Управление паками сохраняет положение списка при изменениях. Версии с сохранёнными партиями доступны для удаления с двойным подтверждением; можно удалить все старые версии или все паки. Связанные локальные и сетевые истории очищаются вместе с удалёнными версиями.","В «Моих партиях» появилась полная очистка локальных и сетевых сохранений с подтверждением.","Коллекция 0.5.1 обновляет Лудо до 0.1.5: выход с базы одним нажатием, раздельные старт и вход в дом, безопасные клетки со звёздами.","Акулина: публичная анимация закрытого обмена без значения карты, очки по порядку выхода. Пексесо: ошибки бота и передача хода без кнопки. Ятзи: стабильная высота строк и положение таблицы при действиях."]},{"version":"0.16.0","changes":["Стабильный выпуск с коллекцией 0.5.0 из 12 игр. Закрытые передачи Акулины видят только участники; публичный сброс пары сохранён.","PWA предлагает постоянную кнопку обновления и активирует новый shell после проверки всех открытых окон, сохраняя партии и offline-данные.","Флот Морского боя показан отдельными счётчиками по длине с красным нулём; оба поля центрируются в портрете и коротком landscape. Зоны действий всех игр проверены на стабильность при появлении кнопок.","Лудо завершает ход сразу после гарантированного выхода без шестёрки. В Ятзи можно освободить удержанный кубик до третьего броска; размер области управления не меняется. Аватары игровых паков используют общую светлую палитру."]},{"version":"0.15.0","changes":["Кубок занимает место лобби после завершения партии, включая ранние ходы её истории; новая партия возвращает лобби.","Общая кнопка добавления игрока в лобби и панели партии.","Прокрутка многострочной руки определяет контейнер отдельно для каждой оси, включая внешнюю панель игрока, недоступные элементы и чужой ход.","Паковые версии и форматы сетевых команд/сохранений не изменены. [Контракты и проверка](https://github.com/GraphGiraffe/boardgame-playroom/blob/637f7c34f9ba5635249329d3e617dde3bb762d9e/docs/RC17-TOOLBAR-AND-SCROLL.md).","Общий экран удаления локальных и сетевых партий с одинаковыми кнопками отмены/подтверждения.","Руку можно листать за любой элемент, включая недоступный для хода и во время чужой очереди; скролл не совершает действие.","Общий объект справа больше не сдвигает список соперников вниз в горизонтальном режиме.","Общий круглый счётчик фигур `pieces`; компактные карточки шашек без текстовых подписей стороны и количества.","Контракты и проверка: [RC16-INTERFACE](https://github.com/GraphGiraffe/boardgame-playroom/blob/637f7c34f9ba5635249329d3e617dde3bb762d9e/docs/RC16-INTERFACE.md). Stable и деплой отдельно.","Независимые ситуации UNO и таймеры каждого игрока; чужой ход больше не закрывает возможность обвинения.","Повтор сетевой команды только после ошибки доставки, один автоматический повтор с прежним ID, без двойного хода.","Центрированный переключатель «Локальная / Сетевая», значок игрока с плюсом, прокрутка справа от перетаскиваемых мест.","Видимая кнопка «Остановить и сохранить» у хоста; остановка ожидает сохранения принятого хода и сохраняет комнату.","Семь костей домино помещаются без горизонтального скролла; общий кубик снизу в портрете и справа в альбомной ориентации.","В архиве выделены все люди, игравшие с этого устройства. PWA проверяет целостность полного обновления и ждёт закрытия открытых вкладок.","Контракты, проверка и границы: [RC15-INTERACTIONS](https://github.com/GraphGiraffe/boardgame-playroom/blob/637f7c34f9ba5635249329d3e617dde3bb762d9e/docs/RC15-INTERACTIONS.md).","Общие окна с отдельной прокруткой, непрозрачной шапкой и анимациями под затемнением; лобби сохраняет фокус и положение прокрутки.","Сетевой ввод восстанавливается после закрытия окна и позднего ACK. Общие настройки и карточки продолжения; собственный ник в архиве выделен по сохранённой идентичности.","Остановка хостом сохраняет незавершённую партию и возвращает всех в лобби без разрыва RTC. Завершённые результаты каждый закрывает самостоятельно.","Компактные руки в истории, общий кубик Змей; независимые штрафы UNO по цели.","Звуковой handle 0 допустим; первый запуск ожидает Wasm, закрытие окна отменяет подготовку. Проверяемая упаковка приватного Pages ZIP с сохранением защиты.","Контракты и проверка: [RC14-INTERACTIONS](https://github.com/GraphGiraffe/boardgame-playroom/blob/637f7c34f9ba5635249329d3e617dde3bb762d9e/docs/RC14-INTERACTIONS.md).","Закрытие и восстановление лобби при продолжении Offline.","Возврат из меню в сетевую игру без разрыва RTC, отдельный полный выход.","Относительная рассадка и общие значки игровых статусов.","Проверки и ограничения: [RC13-NAVIGATION](https://github.com/GraphGiraffe/boardgame-playroom/blob/637f7c34f9ba5635249329d3e617dde3bb762d9e/docs/RC13-NAVIGATION.md)."]},{"version":"0.13.0","changes":["Приложение, движок и игровые паки разделены по ответственности и репозиториям.","Установка и обновление офлайн-паков через интерфейс, проверка API и сохранение прежних версий.","Партии и повторы привязаны к версии пака; старые сохранения прототипа используют 0.1.0.","Общие анимации и подсказки перенесены в core; специальные правила и раскладки принадлежат пакам.","Отдельные сборки: базовое приложение без игр и удобный HTML с пятью начальными паками.","Добавлен план документации и гайдлайнов авторов игр. Сетевой мультиплеер остаётся в плане."]}]};
